import {useStyle, type UseStyleResult, type GenerateStyle} from '@ant-design/pro-provider';
import {type ExtraProAliasToken} from '@/type/design-token';
import {PackageConst} from '@/constant/PackageConst';


const buildFieldStyle: GenerateStyle<ExtraProAliasToken> = (token) => {
    return {
        [`${token.componentCls}`]: {
            display: 'flex',
            [`&-fulfil-span`]: {
                display: 'inline-block',
            },
            [`&-action`]: {
                [`${token.componentCls}-action-input`]: {
                    height: 20,
                    marginTop: 1,
                },
                [`${token.componentCls}-action-tag`]: {
                    cursor: 'pointer',
                }
            },
            [`&&-pro-field`]: {
                minHeight: 46,
                [`${token.antCls}-form-item-control-input`]: {
                    alignItems: 'unset !important',
                    [`${token.antCls}-input-affix-wrapper-sm ${token.antCls}-input-sm`]: {
                        fontSize: token.fontSizeSM,
                    }
                }
            },
            [`&:not(&-pro-field)`]: {
                [`${token.anrCls}-input-sm`]: {
                    fontSize: token.fontSizeSM,
                    height: 21,
                }
            }
        },
        [`${token.componentCls}-compact-margin`]: {
            marginBottom: 0,
        }
    };
}


export function useFieldStyle(prefixCls: string): UseStyleResult {
    return useStyle(`${PackageConst.PACKAGE_NAME}:TagInput`, (token) => {
        const mesh: ExtraProAliasToken = {
            prefixCls,
            componentCls: `.${prefixCls}`,
            ...token,
        };
        return [buildFieldStyle(mesh)];
    });
}
