import React from 'react';
import {Space} from 'antd';
import {FormContext} from 'antd/es/form/context';
import {type SpaceSize} from 'antd/es/space';
import classNames from 'classnames';
import {type WithFalse, type AxisDirectionType} from '@/type/declaration';
import {useFieldStyle} from './style';


export type LabelPresetStyle = WithFalse<'label-prior' | 'field-prior'>;


export type LabelFieldProps = React.PropsWithChildren<{
    /**
     * @description The CSS class prefix of the component
     * @description.zh-CN 组件的 CSS 类名前缀
     * @description.zh-TW 組件的 CSS 類名前綴
     * @default 'abp-label-field'
     */
    clazzPrefix?: string;

    /**
     * @description The CSS class name of the container div
     * @description.zh-CN 容器 div 的 CSS 类名
     * @description.zh-TW 容器 div 的 CSS 類名
     */
    containerClazz?: string;

    /**
     * @description The CSS style of the container div
     * @description.zh-CN 容器 div 的 CSS 样式
     * @description.zh-TW 容器 div 的 CSS 樣式
     */
    containerStyle?: React.CSSProperties;

    /**
     * @description The layout of the label and the field
     * @description.zh-CN 标签和内容的布局样式
     * @description.zh-TW 標簽和內容的布局樣式
     * @default 'horizontal'
     */
    layout?: AxisDirectionType;

    /**
     * @description The label element
     * @description.zh-CN 标签节点
     * @description.zh-TW 標簽節點
     */
    label?: React.ReactNode | (() => React.ReactNode | undefined);

    /**
     * @description The CSS class name of the label
     * @description.zh-CN 标签的 CSS 类名
     * @description.zh-TW 標簽的 CSS 類名
     */
    labelClazz?: string;

    /**
     * @description The CSS style of the label
     * @description.zh-CN 标签的 CSS 样式
     * @description.zh-TW 標簽的 CSS 樣式
     */
    labelStyle?: React.CSSProperties;

    /**
     * @description The delimiter between the label and the content
     * @description.zh-CN 标签和内容之间的分隔符
     * @description.zh-TW 標簽和內容之間的分隔符
     * @default ':'
     */
    delimiter?: React.ReactNode;

    /**
     * @description The layouts when should display the delimiter
     * @description.zh-CN 需要显示分隔符的布局样式
     * @description.zh-TW 需要顯示分隔符的布局樣式
     * @default ['horizontal', 'vertical']
     */
    delimiterInLayout?: AxisDirectionType[] | false;

    /**
     * @description The field element
     * @description.zh-CN 字段节点
     * @description.zh-TW 字段節點
     */
    field?: React.ReactNode | (() => React.ReactNode | undefined);

    /**
     * @description The CSS class name of the field
     * @description.zh-CN 字段节点的 CSS 类名
     * @description.zh-TW 字段節點的 CSS 類名
     */
    fieldClazz?: string;

    /**
     * @description The CSS style of the field
     * @description.zh-CN 字段节点的 CSS 样式
     * @description.zh-TW 字段節點的 CSS 樣式
     */
    fieldStyle?: React.CSSProperties;

    /**
     * @description The space size
     * @description.zh-CN 间距大小
     * @description.zh-TW 間距大小
     */
    spaceSize?: SpaceSize;

    /**
     * @description Whether is required field or not
     * @description.zh-CN 是否为必填字段
     * @description.zh-TW 是否為必填字段
     */
    required?: boolean;

    /**
     * @description Whether to match the width of parent element or not
     * @description.zh-CN 是否匹配父节点的宽度
     * @description.zh-TW 是否匹配父節點的寬度
     */
    widthBlock?: boolean;

    /**
     * @description Whether to hide the label (and delimiter) when it is empty
     * @description.zh-CN 当标签为空时是否隐藏标签和分隔符
     * @description.zh-TW 當標簽為空時是否隱藏標簽和分隔符
     */
    hideLabelWhenEmpty?: boolean;

    /**
     * @description Whether to hide the field when it is empty
     * @description.zh-CN 当内容为空时是否隐藏内容
     * @description.zh-TW 當內容為空時是否隱藏內容
     */
    hideFieldWhenEmpty?: boolean;

    /**
     * @description The preset style of the component
     * @description.zh-CN 预设样式
     * @description.zh-TW 預設樣式
     * @default 'field-prior'
     */
    presetStyle?: LabelPresetStyle;
}>;


/**
 * Component for displaying a field with a label
 *
 * @author David Hsing
 */
export const LabelField: React.FC<LabelFieldProps> = (props?: LabelFieldProps) => {
    const formContext = React.useContext(FormContext);
    const clazzPrefix = props?.clazzPrefix ?? 'abp-label-field';

    // Initialize the default props
    const {
        delimiter = ':',
        delimiterInLayout = ['horizontal', 'vertical'],
        layout = 'horizontal',
        presetStyle = 'field-prior',
    } = props ?? {};

    const fieldStyle = useFieldStyle(clazzPrefix);

    const buildLabelDom = () => {
        const income = !props?.label ? undefined : (typeof props.label === 'function' ? props.label() : props.label);
        if (!income && props?.hideLabelWhenEmpty) {
            return undefined;
        }
        return (
            <div
                className={classNames(`${clazzPrefix}-label`, props?.labelClazz)}
                style={props?.labelStyle}
            >
                {income}
                {!delimiterInLayout ? undefined : (delimiterInLayout.includes(layout) ? delimiter : undefined)}
            </div>
        );
    };

    const buildFieldDom = () => {
        const income = !props?.field ? props?.children : (typeof props.field === 'function' ? props.field() : props.field);
        if (!income && props?.hideFieldWhenEmpty) {
            return undefined;
        }
        return (
            <div
                className={classNames(`${clazzPrefix}-field`, props?.fieldClazz)}
                style={props?.fieldStyle}
            >
                {income}
            </div>
        );
    };

    return (
        <div
            className={classNames(clazzPrefix, fieldStyle.hashId, ((formContext?.requiredMark !== false && props?.required) ? `${clazzPrefix}-required` : undefined), (props?.widthBlock ? `${clazzPrefix}-width-block` : undefined), (presetStyle ? `${clazzPrefix}-${presetStyle}` : undefined), props?.containerClazz)}
            style={props?.containerStyle}
        >
            <Space className={`${clazzPrefix}-space-${layout}`} direction={layout} size={props?.spaceSize}>
                {buildLabelDom()}
                {buildFieldDom()}
            </Space>
        </div>
    );
};
