import {useStyle, type UseStyleResult, type GenerateStyle} from '@ant-design/pro-provider';
import {type ExtraProAliasToken} from '@/type/design-token';
import {PackageConst} from '@/constant/PackageConst';


const buildFieldStyle: GenerateStyle<ExtraProAliasToken> = (token) => {
    return {
        [`${token.componentCls}`]: {
            [`&&-width-block > ${token.antCls}-space`]: {
                width: '100%',
            },
            [`&&-required &-label::before`]: {
                display: 'inline-block',
                marginRight: token.marginXXS,
                color: token.colorErrorText,
                content: '"*"',
            },
            [`&&-label-prior &-space-horizontal`]: {
                display: 'flex',
                [`${token.antCls}-space-item:first-of-type`]: {
                    display: 'flex',
                    flex: 1,
                    [`${token.componentCls}-label`]: {
                        display: 'flex',
                        flex: 1,
                    }
                },
                [`${token.antCls}-space-item:last-of-type`]: {
                    display: 'flex',
                    flex: 'none',
                    width: 'fit-content',
                }
            },
            [`&&-field-prior &-space-horizontal`]: {
                display: 'flex',
                [`${token.antCls}-space-item:first-of-type`]: {
                    display: 'flex',
                    flex: 'none',
                    width: 'fit-content',
                },
                [`${token.antCls}-space-item:last-of-type`]: {
                    display: 'flex',
                    flex: 1,
                    [`${token.componentCls}-field`]: {
                        display: 'flex',
                        flex: 1,
                    }
                }
            },
            [`&-space-vertical`]: {
                display: 'flex',
                flex: 1,
                [`${token.antCls}-space-item`]: {
                    [`${token.componentCls}-label, ${token.componentCls}-field`]: {
                        display: 'flex',
                        flex: 1,
                    }
                }
            }
        }
    };
}


export function useFieldStyle(prefixCls: string): UseStyleResult {
    return useStyle(`${PackageConst.PACKAGE_NAME}:LabelField`, (token) => {
        const mesh: ExtraProAliasToken = {
            prefixCls,
            componentCls: `.${prefixCls}`,
            ...token,
        };
        return [buildFieldStyle(mesh)];
    });
}
